function renderEvents(lang){
 const previous={};document.querySelectorAll('#event-form [name]').forEach(e=>previous[e.name]=e.value);
 const t=eventCopy[lang],u=eventUpgrade[lang];language=lang;
 document.documentElement.lang=lang==='pt'?'pt-PT':lang;document.title=t.title;document.querySelector('meta[name="description"]').content=t.desc;document.querySelector('.skip').textContent=localLabel(lang,'Ir para o conteúdo','Saltar al contenido','Skip to content');
 const options=arr=>arr.map((v,i)=>`<option value="${i}">${v}</option>`).join('');
 const brand=`<a class="brand" href="index.html?lang=${lang}"><b>Cheers</b><small>EXPERIENCES</small></a>`;
 document.getElementById('app').innerHTML=`
 <header class="header"><div class="wrap header-inner">${brand}<nav class="nav" id="navigation" aria-label="${localLabel(lang,'Navegação principal','Navegación principal','Main navigation')}"><a href="index.html?lang=${lang}">${t.hotels}</a><a href="eventos.html?lang=${lang}" aria-current="page">${t.events}</a><a class="btn btn-small" href="#event-contact">${t.cta} ${arrow}</a></nav>${languageButtons(lang)}<button class="menu-toggle" aria-expanded="false" aria-controls="navigation">${t.menu}</button></div></header>
 <main id="main"><section class="hero event-hero"><img class="hero-image" src="hero.webp" alt="" width="1672" height="941" fetchpriority="high"><div class="wrap hero-content"><div class="business-switch"><a href="index.html?lang=${lang}">${t.hotels}</a><a href="eventos.html?lang=${lang}" aria-current="page">${t.events}</a></div><span class="eyebrow">${t.eyebrow}</span><h1>${t.headline}</h1><p class="hero-copy">${t.intro}</p><p class="hero-audience">${localLabel(lang,'Casamentos · Eventos empresariais · Celebrações','Bodas · Eventos de empresa · Celebraciones','Weddings · Corporate events · Celebrations')}</p><div class="hero-actions"><a class="btn" href="#event-contact">${t.cta} ${arrow}</a><a class="text-link" href="#formats">${t.heroLink} ↓</a></div></div></section>
 ${proofStrip(lang,true)}
 <nav class="section-nav wrap" aria-label="${localLabel(lang,'Nesta página','En esta página','On this page')}"><a href="#celebrations">${localLabel(lang,'Casamentos','Bodas','Weddings')}</a><a href="#corporate">Corporate</a><a href="#experiences">${localLabel(lang,'Experiências','Experiencias','Experiences')}</a><a href="#event-planning">${localLabel(lang,'Preparação','Preparación','Planning')}</a><a href="#formats">${localLabel(lang,'Formatos','Formatos','Formats')}</a><a href="#event-contact">${t.cta}</a></nav>
 <section class="section event-emotion"><div class="wrap"><span class="eyebrow section-label">We make moments worth remembering.</span><h2>${u.emotionalTitle}</h2><p class="wide-lead">${u.emotionalText}</p><div class="touch-grid event-area-grid">${u.areas.map(x=>`<article><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div></div></section>
 <section class="section" id="celebrations"><div class="wrap split"><div><span class="eyebrow section-label">${t.weddingLabel}</span><h2>${t.weddingTitle}</h2></div><div><p class="event-lead">${t.weddingText}</p><p class="event-venue">${t.venue}</p></div></div><div class="wrap event-scale"><h3>${t.scale}</h3><p>${t.scaleText}</p><p class="flex-note">${u.flex}</p></div></section>
 <section class="section signature-section"><div class="wrap split"><div><span class="eyebrow section-label">Signature Cocktails</span><h2>${u.signatureTitle}</h2></div><div><p class="event-lead">${u.signatureText}</p><p class="section-note">${u.signatureNote}</p></div></div></section>
 <section class="section group-section" id="corporate"><div class="wrap split"><div><span class="eyebrow">Corporate Events</span><h2>${u.corporateTitle}</h2><p class="wide-lead">${u.corporateText}</p><a class="btn" href="#event-contact" data-corporate>${u.corporateCTA} ${arrow}</a></div><div>${list(u.corporateItems)}<p class="section-note">${u.corporateNote}</p></div></div></section>
 <section class="section services"><div class="wrap"><span class="eyebrow section-label">${t.servicesLabel}</span><p class="inclusive-line">${u.inclusive}</p><div class="service-grid">${t.services.map((s,i)=>`<article class="service"><span class="service-tag">0${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p></article>`).join('')}</div></div></section>
 <section class="section" id="experiences"><div class="wrap"><h2>${u.packagesTitle}</h2><div class="event-formats light-formats">${u.packages.map((x,i)=>`<article><span class="step-number">0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p><a class="text-link" href="#event-contact" data-experience="${i}">${conversion[lang].choose} ${arrow}</a></article>`).join('')}</div><p class="section-note">${u.packagesNote}</p></div></section>
 <section class="section potential" id="formats"><div class="wrap"><span class="eyebrow">${t.formatsLabel}</span><h2>${t.formatsTitle}</h2><div class="event-formats">${t.formats.map((s,i)=>`<article><span class="step-number">0${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p></article>`).join('')}</div><p class="event-format-note">${t.formatNote}</p></div></section>
 <section class="section"><div class="wrap split"><div><h2>${t.temporaryTitle}</h2><p class="event-venue">${t.temporaryText}</p></div><div><span class="eyebrow section-label">${t.areaLabel}</span><h3 class="event-area-title">${t.areaTitle}</h3><ul class="event-areas">${['Viseu','Coimbra','Aveiro','Porto','Vila Real','Guarda','Algarve','Costa Blanca'].map(a=>`<li>${a}</li>`).join('')}</ul><p>${t.areaNote}</p></div></div></section>
 ${eventPlanning(lang)}
 ${eventQuestions(lang)}
 <section class="section contact" id="event-contact"><div class="wrap split"><div><span class="eyebrow">${t.cta}</span><h2>${t.contactTitle}</h2><p class="contact-copy">${t.contactText}</p><div class="contact-links"><a class="btn whatsapp-direct" href="https://wa.me/351927653087?text=${encodeURIComponent(t.introMessage)}" target="_blank" rel="noopener noreferrer">${t.wa} ${arrow}</a><a href="mailto:sucessomacico@gmail.com">sucessomacico@gmail.com</a><a href="tel:+351927653087">+351 927 653 087</a></div></div>
 <form id="event-form" class="contact-form"><p class="form-hint">${conversion[lang].contactHint}</p><p id="experience-choice" class="experience-choice" ${selectedExperience===null?'hidden':''}>${selectedExperience===null?'':conversion[lang].chosen+': '+u.packages[selectedExperience][0]}</p><label>${t.name} *<input name="name" autocomplete="name" required maxlength="100"></label><div class="form-row"><label>${t.type}<select name="type">${options(t.types)}</select></label><label>${t.date}<input type="date" name="date"></label></div><label>${t.place} *<input name="place" required maxlength="200"></label><div class="form-row"><label>${t.guests} *<input type="number" name="guests" required min="1" step="1" inputmode="numeric"></label><label>${t.model}<select name="model">${options(t.models)}</select></label></div><label>${u.need}<select name="need">${u.needs.map((v,i)=>`<option value="${i}" ${i===6?'selected':''}>${v}</option>`).join('')}</select></label><label>${t.message}<textarea name="message" maxlength="1500" placeholder="${t.placeholder}"></textarea></label><button class="btn" type="submit">${t.submit} ${arrow}</button><p class="fine">${t.note}</p><a class="text-link" id="event-email" href="mailto:sucessomacico@gmail.com">${t.email} ${arrow}</a><p id="event-status" class="form-status" role="status" hidden></p></form></div></section></main>
 ${crossBusiness(lang,true)}
 <footer class="footer"><div class="wrap"><div class="footer-top">${brand}<p>${t.footer}</p><a class="text-link" href="index.html?lang=${lang}">${t.hotels} ${arrow}</a></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Cheers Experiences<br>${t.legal}</span><span>${t.imageNote}</span></div></div></footer>`;
 updateMetadata(lang,true);bindCommercialChoices(lang,true);
 document.querySelector('[data-corporate]').addEventListener('click',()=>{selectedExperience=null;document.getElementById('experience-choice').hidden=true;document.querySelector('#event-form [name=type]').value='3';document.querySelector('#event-form [name=need]').value='4';});
 document.querySelectorAll('#event-form [name]').forEach(e=>{if(previous[e.name]!==undefined)e.value=previous[e.name]});
 document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{const u=new URL(location.href);u.searchParams.set('lang',b.dataset.lang);history.replaceState(null,'',u);rememberLanguage(b.dataset.lang);renderEvents(b.dataset.lang);document.querySelector(`[data-lang="${b.dataset.lang}"]`).focus({preventScroll:true});}));
 const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('.nav');
 function close(){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.textContent=t.menu;}
 toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?t.close:t.menu;});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));document.onkeydown=e=>{if(e.key==='Escape'&&nav.classList.contains('open')){close();toggle.focus();}};
 const form=document.getElementById('event-form');
 function message(){const d=new FormData(form);const value=k=>String(d.get(k)||'').trim();return `${t.introMessage}\n\n${t.name}: ${value('name')}\n${t.type}: ${t.types[Number(value('type'))]}\n${t.date}: ${value('date')||'—'}\n${t.place}: ${value('place')}\n${t.guests}: ${value('guests')}\n${t.model}: ${t.models[Number(value('model'))]}\n${u.need}: ${u.needs[Number(value('need'))]}${selectedExperience===null?'':'\n'+conversion[lang].chosen+': '+u.packages[selectedExperience][0]}\n\n${value('message')}`;}
 form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const a=document.createElement('a');a.href='https://wa.me/351927653087?text='+encodeURIComponent(message());a.target='_blank';a.rel='noopener noreferrer';document.body.append(a);a.click();a.remove();const status=document.getElementById('event-status');status.textContent=t.status;status.hidden=false;});
 document.getElementById('event-email').addEventListener('click',e=>{e.currentTarget.href='mailto:sucessomacico@gmail.com?subject='+encodeURIComponent(t.subject)+'&body='+encodeURIComponent(message());});
}
